// ---- config -----------------------------------------------------------
var cotType = "a-n-G-E-S-E"; // Ground/Equipment/Sensor/Emplaced Sensor -- distinct
                              // equipment-frame icon (not the unit-square) for a
                              // fixed radio node reporting position
// Same Tennessee + buffer bounding box used in the Marinesia AIS and
// Winlink VHF/UHF flows, for consistency.
var TN_BBOX = { latMin: 34.7, latMax: 37.0, lonMin: -90.6, lonMax: -81.3 };
var staleMinutes = 60; // Meshtastic nodes report position infrequently
// -------------------------------------------------------------------------

function esc(s) {
    return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;")
        .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// meshtastic-decode's "nested" output shape is:
//   msg.payload = { message: {$typeName, latitudeI, ...}, metadata: {from, portNum, ...}, envelope: {channelId, gatewayId}, radio: {...}, flags: {...} }
//   msg._meshtastic = { encrypted, from, to, channel, packetId }
// $typeName lives on payload.message, NOT on payload itself.
var payload = msg.payload;
if (!payload || !payload.message) { return null; }
var meta = payload.metadata || {};
var envelope = payload.envelope || {};
var p = payload.message;

// Only handle Position reports and MapReports -- both carry lat/lon and are
// the two message types that actually make it through the public server's
// filtering with usable location data. Other portnums (NODEINFO, TELEMETRY,
// TEXT_MESSAGE, ROUTING/ACK, etc.) also flow through this same decode node
// and are expected to be dropped here.
var isPosition = meta.portNum === "POSITION_APP" || p.$typeName === "meshtastic.Position";
var isMapReport = meta.portNum === "MAP_REPORT_APP" || p.$typeName === "meshtastic.MapReport";
if (!isPosition && !isMapReport) { return null; }
if (p.latitudeI === undefined || p.longitudeI === undefined) { return null; }

var lat = p.latitudeI * 1e-7;
var lon = p.longitudeI * 1e-7;

// Learn node locations for the "TN gateways only" filter upstream.
// Gateways report their own position (map reports / position packets), so
// this builds a lookup of which uplinking nodes sit in or near Tennessee.
(function () {
    var num = meta.from !== undefined ? meta.from : (msg._meshtastic && msg._meshtastic.from);
    if (num === undefined || num === null) return;
    var key = (Number(num) >>> 0).toString(16);
    var M = 0.5; // extra margin (deg) so border gateways that hear TN nodes are kept
    var inTN = lat >= TN_BBOX.latMin - M && lat <= TN_BBOX.latMax + M &&
               lon >= TN_BBOX.lonMin - M && lon <= TN_BBOX.lonMax + M;
    var gw = flow.get("meshGatewayTN") || {};
    var changed = false;
    // The sender's own location is authoritative for the sender
    if (gw[key] !== inTN) { gw[key] = inTN; changed = true; }
    // The uplinking gateway heard this sender over RF, so it is near it.
    // A TN sighting marks the gateway TN; an out-of-state one only marks it
    // out if it has not already been seen relaying TN traffic.
    if (envelope.gatewayId) {
        var g = parseInt(String(envelope.gatewayId).replace(/^!/, ""), 16);
        if (!isNaN(g)) {
            var gk = (g >>> 0).toString(16);
            if (inTN && gw[gk] !== true) { gw[gk] = true; changed = true; }
            else if (!inTN && gw[gk] === undefined) { gw[gk] = false; changed = true; }
        }
    }
    if (changed) { flow.set("meshGatewayTN", gw); }
})();

// Drop anything outside the TN + buffer box.
if (lat < TN_BBOX.latMin || lat > TN_BBOX.latMax ||
    lon < TN_BBOX.lonMin || lon > TN_BBOX.lonMax) {
    return null;
}

// metadata.from (fallback: msg._meshtastic.from) is the actual packet SENDER's
// node number. envelope.gatewayId is the separate uplinking gateway node --
// deliberately not used here, since it would mislabel every peer a gateway
// relays with the gateway's own identity instead of the real sender.
var fromNum = meta.from !== undefined ? meta.from : (msg._meshtastic && msg._meshtastic.from);
var nodeId;
if (fromNum !== undefined && fromNum !== null) {
    nodeId = "!" + (Number(fromNum) >>> 0).toString(16);
} else {
    nodeId = "unknown";
    node.warn("Build COT: no metadata.from / _meshtastic.from found on msg -- node ID will be 'unknown'. Check meshtastic-decode's output shape.");
}

// Look up a real name cached from NODEINFO_APP messages (see the other
// function node) -- MapReport already carries the node's name directly in
// the same packet, so prefer that when present; otherwise fall back to the
// NodeInfo cache, then the raw node ID.
var names = flow.get('meshtastic_names') || {};
var nameInfo = names[nodeId];
var callsign = p.longName || (nameInfo && nameInfo.longName) || nodeId;
var shortName = p.shortName || (nameInfo && nameInfo.shortName);

var now = new Date();
var start = now.toISOString();
var stale = new Date(now.getTime() + staleMinutes * 60 * 1000).toISOString();

var uid = "meshtastic-" + nodeId.replace(/[^A-Za-z0-9]/g, "_");

var remarksParts = ["Meshtastic node " + nodeId, isMapReport ? "Source: Map Report" : "Source: Position"];
if (shortName) { remarksParts.push("Short: " + shortName); }
if (envelope.channelId) { remarksParts.push("Channel: " + envelope.channelId); }
if (envelope.gatewayId) { remarksParts.push("Via gateway: " + envelope.gatewayId); }
if (p.altitude) { remarksParts.push("Alt: " + p.altitude + "m"); }
if (p.satsInView) { remarksParts.push("Sats: " + p.satsInView); }
var precision = p.precisionBits !== undefined ? p.precisionBits : p.positionPrecision;
if (precision) { remarksParts.push("Precision bits: " + precision + " (public server limits precision)"); }

// ground_track is degrees * 1e5 in the Meshtastic Position protobuf (same
// scaling idea as latitudeI/longitudeI); ground_speed is already m/s.
var course = (p.groundTrack || 0) / 1e5;
var speed = p.groundSpeed || 0;

var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
    '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" ' +
    'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
    '<point lat="' + lat.toFixed(6) + '" lon="' + lon.toFixed(6) + '" hae="' + (p.altitude || 0) + '" ce="9999999.0" le="9999999.0"/>' +
    '<detail>' +
    '<contact callsign="' + esc(callsign) + '"/>' +
    '<track course="' + course + '" speed="' + speed + '"/>' +
    '<remarks>' + esc(remarksParts.join(" | ")) + '</remarks>' +
    '</detail>' +
    '</event>';

msg.payload = cot;
return msg;

// Cache Meshtastic node names (NODEINFO_APP / meshtastic.User) so Position
// CoTs can show a real callsign instead of the raw node ID.
// Same nested shape as Build COT: $typeName is on payload.message, and the
// sender's node number is metadata.from -- keyed to match the nodeId format
// Build COT computes ("!" + hex(from)), not the raw payload.message.id field,
// so name lookups actually hit.
var payload = msg.payload;
if (!payload || !payload.message) { return null; }
var meta = payload.metadata || {};
var p = payload.message;
if (meta.portNum !== "NODEINFO_APP" && p.$typeName !== "meshtastic.User") { return null; }

var fromNum = meta.from !== undefined ? meta.from : (msg._meshtastic && msg._meshtastic.from);
if (fromNum === undefined || fromNum === null) { return null; }
var nodeId = "!" + (Number(fromNum) >>> 0).toString(16);

var names = flow.get('meshtastic_names') || {};
names[nodeId] = { longName: p.longName || '', shortName: p.shortName || '' };
flow.set('meshtastic_names', names);

node.status({ fill: 'blue', shape: 'dot', text: Object.keys(names).length + ' node names cached' });
return null; // this node only updates the cache, nothing to send downstream

// TN gateway filter -- runs BEFORE decrypt/decode to save CPU.
// LongFast topics end in the uplinking gateway ID (msh/US/2/e/LongFast/!a1b2c3d4).
// Build COT records which nodes are in/near TN (flow "meshGatewayTN").
//  - map reports: always pass (low volume; they teach gateway locations)
//  - known TN gateway: pass
//  - known out-of-state gateway: drop
//  - unknown gateway: pass 1 in UNKNOWN_SAMPLE so its location can be learned
var UNKNOWN_SAMPLE = 25;
var t = msg.topic || "";
var c = context.get("c") || { tn: 0, out: 0, unk: 0, map: 0, n: 0 };
c.n++;
var pass = false;
if (t.indexOf("/2/map/") !== -1) { c.map++; pass = true; }
else {
    var gwNum = parseInt(t.split("/").pop().replace(/^!/, ""), 16);
    var gw = flow.get("meshGatewayTN") || {};
    var v = isNaN(gwNum) ? undefined : gw[(gwNum >>> 0).toString(16)];
    if (v === true) { c.tn++; pass = true; }
    else if (v === false) { c.out++; }
    else { c.unk++; pass = (c.unk % UNKNOWN_SAMPLE === 0); }
}
context.set("c", c);
if (c.n % 500 === 0) {
    node.status({ fill: "green", shape: "dot", text: "TN " + c.tn + " | out " + c.out + " | unknown " + c.unk + " | map " + c.map });
}
return pass ? msg : null;

// Drops packets that have no readable payload (not encrypted AND not decoded),
// which otherwise make meshtastic-decode throw ~8 errors/sec. Counts what it drops.
const pkt = msg.payload && msg.payload.packet;
const kind = /\/2\/map\//.test(msg.topic || "") ? "map" : "LongFast";
if (pkt && pkt.payloadVariant && pkt.payloadVariant.case === "decoded") {
    context.set("pass", (context.get("pass") || 0) + 1);
    return msg;
}
const c = context.get("drop") || { map: 0, LongFast: 0 };
c[kind]++; context.set("drop", c);
node.status({ fill: "grey", shape: "dot", text: "passed " + (context.get("pass") || 0) + " | dropped empty: LongFast " + c.LongFast + ", map " + c.map });
return null;
